namespace {
void Stop(nh::ProcessJob& job){if(job.process){TerminateProcess(job.process,0);WaitForSingleObject(job.process,5000);CloseHandle(job.process);job.process=nullptr;}if(job.output){CloseHandle(job.output);job.output=nullptr;}job.busy=false;}
std::string S(const std::filesystem::path& path){return nh::Utf8(path.lexically_normal().make_preferred().wstring());}
std::filesystem::path Exe(const std::filesystem::path& path,bool x86=false){
 std::filesystem::create_directories(path.parent_path());std::vector<char> bytes(512);auto dos=reinterpret_cast<IMAGE_DOS_HEADER*>(bytes.data());dos->e_magic=IMAGE_DOS_SIGNATURE;dos->e_lfanew=64;
 *reinterpret_cast<DWORD*>(bytes.data()+64)=IMAGE_NT_SIGNATURE;auto header=reinterpret_cast<IMAGE_FILE_HEADER*>(bytes.data()+68);header->Machine=x86?IMAGE_FILE_MACHINE_I386:IMAGE_FILE_MACHINE_AMD64;header->NumberOfSections=1;header->SizeOfOptionalHeader=x86?224:240;header->Characteristics=IMAGE_FILE_EXECUTABLE_IMAGE;*reinterpret_cast<WORD*>(bytes.data()+88)=x86?IMAGE_NT_OPTIONAL_HDR32_MAGIC:IMAGE_NT_OPTIONAL_HDR64_MAGIC;std::ofstream(path,std::ios::binary).write(bytes.data(),bytes.size());return path;
}
nh::Json Item(const char* id,const std::filesystem::path& root,const std::filesystem::path& exe,const char* store="Custom",const char* storeId=""){
 return {{"id",id},{"title","Same game title"},{"store",store},{"storeId",storeId},{"installRoot",S(root)},{"executable",S(exe)},{"executableCandidates",nh::Json::array({S(exe)})},{"steamRoot",S(root.parent_path())}};
}
void Merge(nh::HubModel& model,const nh::Json& items){model.MergeDiscovery({{"protocolVersion",2},{"kind","DiscoveryResult"},{"errors",nh::Json::array()},{"games",items}});}
nh::Json Read(const std::filesystem::path& path){std::ifstream in(path);return nh::Json::parse(in);}
void Inspected(nh::HubModel& model,const char* value){
 auto result=model.installer.result;Stop(model.installer);
 nh::Json inspection={{"target",{{"executable",model.games[model.selected].target.path},{"bitness",64}}},{"state",nullptr},{"settings",nh::Json::array()}};
 inspection["settings"].push_back({{"section","DlssNr"},{"key","Strength"},{"type","float"},{"available",true},{"value",value},{"values",nh::Json::array()}});
 std::ofstream(result)<<nh::Json({{"status","Inspected"},{"inspection",inspection}}).dump();
 wchar_t system[MAX_PATH];GetSystemDirectoryW(system,MAX_PATH);auto exe=std::filesystem::path(system)/L"cmd.exe";auto command=nh::Quote(exe.wstring())+L" /d /c exit 0";STARTUPINFOW startup{sizeof(startup)};PROCESS_INFORMATION child{};
 if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&startup,&child))throw std::runtime_error("Inspection fixture failed");CloseHandle(child.hThread);WaitForSingleObject(child.hProcess,5000);model.installer.process=child.hProcess;model.installer.busy=true;model.Poll();
}
}
